mapper.select:
		SELECT /*LGUTLC00200.retrieveSummaryList*/
			   period_name
             , year_basis_week_id AS yyyy_ww
             , large_class_name AS class_name     
             , medium_class_name AS dashboard_report_center
             , report_department_name AS report_department
             , medium_account_name AS medium_account
		     , account_type_name AS account_type
		     , krw_expense_amount AS expense_amount
		  FROM LGEMF_EXPENSE_RESULT_S
		 WHERE 1 = 1

		   AND ledger_id = #{ledger}


		   AND year_basis_week_id = #{yyyyWw}


		   AND account_type_name = #{accountType}


		   AND period_name = #{periodName}


		   AND medium_class_name = #{dashboardReportCenter}


		   AND report_department_name LIKE #{reportDepartment}||'%'


		   AND medium_account_name = #{mediumAccount}

/*LGUTLC00200.retrieveWeekList*/ SELECT week_id AS yyyy_ww , TO_CHAR(start_date,'YYYY-MM-DD')||'~'|| TO_CHAR(end_date,'YYYY-MM-DD') AS week_date FROM (SELECT year_basis_week_id AS week_id , MIN(week_start_date) AS start_date , MAX(week_end_date) AS end_date FROM lgemf_weekly_basis_status_v xwp WHERE xwp.ledger_id = #{ledger} AND xwp.close_status_code IN ('C','O') GROUP BY year_basis_week_id) WHERE 1=1
AND week_id LIKE '%'||#{yyyyWw}||'%'
ORDER BY 1 DESC
